"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { createInfiniteGrid } from "./three/InfiniteGrid";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);
  const overlayRef = useRef(null);
  const wgs84 = "EPSG:4326";
  const webMercator = "EPSG:3857";

  const [status, setStatus] = useState({
    chunks: 0,
    meshes: 0,
    features: 0,
    lastQueryMs: 0,
    lastQueryBounds: null,
  });

  useEffect(() => {
    const container = ref.current;
    if (!container) return;

    const renderer = createRenderer(container);
    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = 60;
    camera.updateProjectionMatrix();

    const controls = createControls(camera, renderer.domElement);

    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "30.5234");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "50.4501");
    const [mx, mz] = proj4(wgs84, webMercator, [startLon, startLat]);

    camera.position.set(mx, 800, mz + 800);
    camera.lookAt(mx, 0, mz);
    controls.target.set(mx, 0, mz);
    controls.update();

    const { scene, cube } = createScene();

    const light = new THREE.DirectionalLight(0xffffff, 3.0);
    light.position.set(1000, 2000, 1000);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0xffffff, 0.8));
    scene.add(new THREE.HemisphereLight(0xffffff, 0x444444, 0.99));

    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    const loader = new ChunkLoader(scene, {
      onProgress: (meta) => {
        setStatus((s) => ({
          chunks: loader.meshGroups.size,
          meshes: meta.meshesTotal || s.meshes,
          features: meta.featuresTotal || s.features,
          lastQueryMs: meta.queryTimeMs || s.lastQueryMs,
          lastQueryBounds: meta.bounds || s.lastQueryBounds,
        }));
      },
    });

    let isLoading = false;
    let controller = null;

    async function updateChunks() {
      if (isLoading) return;
      isLoading = true;

      const [lon, lat] = proj4(webMercator, wgs84, [
        controls.target.x,
        controls.target.z,
      ]);

      const size = 0.2;
      const minLon = lon - size;
      const minLat = lat - size;
      const maxLon = lon + size;
      const maxLat = lat + size;

      if (controller) controller.abort();
      controller = new AbortController();

      try {
        await loader.loadChunk(minLon, minLat, maxLon, maxLat, {
          simplify: 1.0,
          signal: controller.signal,
          useCache: true,
          keyHint: `${minLon}_${minLat}_${maxLon}_${maxLat}`,
        });
      } catch (e) {
      } finally {
        isLoading = false;
      }
    }

    let updateTimeout;
    const debouncedUpdate = () => {
      clearTimeout(updateTimeout);
      updateTimeout = setTimeout(updateChunks, 250);
    };

    controls.addEventListener("change", debouncedUpdate);
    updateChunks();

    // ======== Бесконечная сетка ========
    const inf = createInfiniteGrid({
      size: 10000,
      cell: 50,
      thickness: 0.02,
    });

    scene.add(inf.mesh);
    // ===================================

    let frame;
    const loop = () => {
      cube.rotation.y += 0.005;

      inf.update(camera.position);

      controls.update();
      renderer.render(scene, camera);
      frame = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };

    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frame);
      clearTimeout(updateTimeout);
      controls.removeEventListener("change", debouncedUpdate);
      window.removeEventListener("resize", handleResize);
      cleanupRaycast();
      loader.clearAll();
      container.removeChild(renderer.domElement);
      renderer.dispose();
      cube.geometry.dispose();
      cube.material.dispose();
    };
  }, []);

  return (
    <div className="w-full h-full relative">
      <div ref={ref} className="w-full h-full" />
      <div
        ref={overlayRef}
        style={{
          position: "absolute",
          right: 12,
          top: 12,
          background: "rgba(0,0,0,0.6)",
          color: "white",
          padding: "8px 12px",
          fontSize: 13,
          borderRadius: 6,
          maxWidth: 300,
        }}
      >
        <div>
          <b>Chunks:</b> {status.chunks}
        </div>
        <div>
          <b>Meshes:</b> {status.meshes}
        </div>
        <div>
          <b>Features:</b> {status.features}
        </div>
        <div>
          <b>Last query ms:</b> {status.lastQueryMs}
        </div>
        <div style={{ wordBreak: "break-word" }}>
          <b>Bounds:</b>{" "}
          {status.lastQueryBounds
            ? JSON.stringify(status.lastQueryBounds)
            : "—"}
        </div>
      </div>
    </div>
  );
}
