import * as THREE from "three";

export function createInfiniteGrid(opts = {}) {
  const size = opts.size || 10000;
  const cell = opts.cell || 50;
  const thickness = opts.thickness || 0.02;
  const color = opts.color || new THREE.Color(0x444444);

  const geo = new THREE.PlaneGeometry(size, size, 1, 1);
  geo.rotateX(-Math.PI / 2);

  const uniforms = {
    uColor: { value: color },
    uCell: { value: cell },
    uThickness: { value: thickness },
    uWorldPos: { value: new THREE.Vector3() },
  };

  const mat = new THREE.ShaderMaterial({
    uniforms,
    transparent: true,
    depthWrite: false,
    vertexShader: `
      varying vec3 vWorldPos;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldPos = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      varying vec3 vWorldPos;
      uniform vec3 uColor;
      uniform float uCell;
      uniform float uThickness;

      void main() {
        float gx = abs(fract(vWorldPos.x / uCell) - 0.5);
        float gz = abs(fract(vWorldPos.z / uCell) - 0.5);
        float d = min(gx, gz);
        float line = step(d, uThickness);
        gl_FragColor = vec4(uColor, line);
      }
    `,
  });

  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;

  function update(camPos) {
    mesh.position.set(camPos.x, 0, camPos.z);
  }

  return { mesh, update };
}
